sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float2 amzp_center;
uniform float amzp_zoom;
uniform float amzp_spin;
uniform float amzp_chroma;
uniform float amzp_chromaMode;
uniform float amzp_focus;
uniform float amzp_falloff;
uniform float amzp_boost;
uniform float amzp_threshold;
uniform float amzp_transparentEdge;
uniform float amzp_mixAmt;
uniform float amzp_samples;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float4 at(float2 uv) {
        if ((amzp_transparentEdge>0.5)) {
            if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return float4(0.0);
        } else {
            uv = clamp(uv, 0.0, 1.0);
        }
        return amzTexture(0, l2s(uv));
    }
    float4 boosted(float4 c) {
        if (amzp_boost <= 0.0001) return c;
        float3 s = c.a > 0.0001 ? c.rgb / c.a : float3(0.0);
        float l = max(s.r, max(s.g, s.b));
        float k = smoothstep(amzp_threshold, min(amzp_threshold + 0.25, 1.0001), l) * amzp_boost * 2.0;
        return float4(c.rgb * (1.0 + k), c.a);
    }
    float ign(float2 p) { return fract(52.9829189 * fract(dot(p, float2(0.06711056, 0.00583715)))); }
    void amzRender() {
        float2 W = layer;
        float pxs = screen.zw.x / max(screen.zw.x, 1.0);
        float2 p = amzLayerNorm() * W;
        float2 C = W * 0.5 + float2(amzp_center.x, -amzp_center.y) * pxs;
        float2 d = p - C;
        float r = length(d);
        float fr = max(amzp_focus * pxs, 0.0);
        float amt = smoothstep(fr, fr + max(amzp_falloff * pxs, 1.0), r);
        if (fr <= 0.0) amt = 1.0;
        float4 src = at(amzLayerNorm());
        float n = clamp(floor(amzp_samples + 0.5), 4.0, 64.0);
        float j = ign(p);
        float ch = max(amzp_chroma, 0.0) * 0.5;
        float sgn = int(amzp_chromaMode) == 0 ? 1.0 : -1.0;
        float spinR = radians(amzp_spin) * amt;
        float zoomA = amzp_zoom * amt;
        float4 acc = float4(0.0);
        float3 accC = float3(0.0);
        float wsum = 0.0;
        for (int i = 0; i < 64; i++) {
            float fi = float(i);
            if (fi >= n) break;
            float t = (fi + j) / n - 0.5;
            float w = 1.0 - abs(t) * 0.6;
            float3 tt = float3(t) * (1.0 + sgn * ch * float3(1.0, 0.0, -1.0));
            float4 cR, cG, cB;
            if (ch < 0.0005) {
                float sc0 = 1.0 - zoomA * t;
                float an0 = spinR * t;
                float2 q0 = C + float2(cos(an0) * d.x - sin(an0) * d.y, sin(an0) * d.x + cos(an0) * d.y) * sc0;
                float4 s0 = boosted(at(q0 / W));
                acc += s0 * w;
                wsum += w;
                continue;
            }
            for (int k = 0; k < 3; k++) {
                float ts = k == 0 ? tt.r : (k == 1 ? tt.g : tt.b);
                float sc = 1.0 - zoomA * ts;
                float an = spinR * ts;
                float cs = cos(an), sn = sin(an);
                float2 q = C + float2(cs * d.x - sn * d.y, sn * d.x + cs * d.y) * sc;
                float4 s = boosted(at(q / W));
                if (k == 0) cR = s; else if (k == 1) cG = s; else cB = s;
            }
            acc += float4(cR.r, cG.g, cB.b, (cR.a + cG.a + cB.a) / 3.0) * w;
            wsum += w;
        }
        float4 blur = acc / max(wsum, 0.0001);
        blur.rgb = min(blur.rgb, float3(blur.a) * 4.0);
        float4 outc = mix(boosted(src), blur, amt);
        outc.rgb = min(outc.rgb, float3(outc.a));
        amzOutput = mix(src, outc, clamp(amzp_mixAmt, 0.0, 1.0));
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
